WITH account_summary AS (SELECT account_id, COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) AS refund_count, MIN(amount) AS min_amount FROM transactions WHERE is_flagged GROUP BY account_id) SELECT accounts.id, accounts.opened_date, account_summary.refund_count, account_summary.min_amount FROM accounts INNER JOIN account_summary ON accounts.id = account_summary.account_id ORDER BY accounts.opened_date;
